get_header(); ?><main id="main"><header class="nob-page-header"><div class="nob-container"><?php nob_breadcrumbs(); ?><h1><?php the_archive_title(); ?></h1><?php if(get_the_archive_description()): ?><p><?php echo wp_kses_post(get_the_archive_description()); ?></p><?php endif; ?></div></header><section class="nob-section"><div class="nob-container"><?php if(have_posts()): ?><div class="nob-card-grid"><?php while(have_posts()):the_post();get_template_part('template-parts/content','card');endwhile; ?></div><?php the_posts_pagination(array('mid_size'=>2,'prev_text'=>'←','next_text'=>'→'));else: ?><div class="nob-empty"><h2><?php esc_html_e('No resources found','notonlybook-modern'); ?></h2><p><?php esc_html_e('Try another subject, year or search term.','notonlybook-modern'); ?></p><?php get_search_form(); ?></div><?php endif; ?></div></section></main><?php get_footer(); ?>